          '[StorageNewsletter: JEDEC and Industry Leaders Collaborate to Release JESD270-4 HBM4 Standard](https://www.storagenewsletter.com/2025/04/17/jedec-and-industry-leaders-collaborate-to-release-jesd270-4-hbm4-standard/) -- HBM4: up to 2 TB/s over a 2048-bit interface',
          '[EE Times Asia: SEMIFIVE, ICY Tech Achieve Successful Tape-out of 8nm eMRAM-Based Edge AI SoC](https://www.eetasia.com/?p=73817) -- companies\' claim: on-device inference for models up to 2B parameters',
