        imageCaption: 'Coût énergétique par opération 32 bits : l\'accès DRAM coûte 500+ pJ (>130x une multiplication flottante 32 bits), l\'accès SRAM ~5 pJ, et la multiplication elle-même seulement ~3,7 pJ (valeurs approximatives à 45 nm, Horowitz, ISSCC 2014 ; les nœuds modernes diffèrent).',
