      'software-alternative': {
        id: 'software-alternative',
        title: 'L\'alternative logicielle: compression du cache KV avec TurboQuant',
        content: [
          'Pendant que les chercheurs matériels travaillent sur le calcul en mémoire MRAM, les ingénieurs logiciels attaquent le goulot d\'étranglement mémoire sous un autre angle: **la compression.**',
          '**Google TurboQuant (ICLR 2026, publié en mars 2026):**',
        ],
        items: [
          'Selon Google Research, TurboQuant compresse le cache KV (clé-valeur) de l\'inférence par transformeur à **3 bits** — contre les formats 16 bits ou 8 bits habituels.',
          '**Réduction d\'au moins 6×** de l\'empreinte mémoire du cache KV (Google Research, sur des tâches needle-in-haystack). En inférence à long contexte, le cache KV peut occuper une grande part de la mémoire.',
          '**Aucune perte de précision rapportée** par Google sur ses propres benchmarks, y compris les évaluations needle-in-haystack (récupération en long contexte) ; l\'[article arXiv](https://arxiv.org/abs/2504.19874) rapporte une neutralité de qualité à 3,5 bits par canal.',
          '**Jusqu\'à 8× d\'accélération** dans le calcul des logits d\'attention sur GPU H100 (TurboQuant 4 bits contre clés 32 bits non quantifiées), selon Google Research ; il ne s\'agit pas d\'une accélération de bout en bout.',
          '**Selon Google Research, aucun entraînement ni fine-tuning n\'est nécessaire.** L\'intégration dans un pipeline d\'inférence existant exige encore une implémentation dans une bibliothèque.',
          'Comment ça fonctionne: Un processus en deux étapes — PolarQuant (quantification en coordonnées polaires avec centroïdes de Lloyd-Max) + QJL (transformée quantifiée de Johnson-Lindenstrauss, qui ajoute une correction d\'erreur pour préserver la précision du produit scalaire à compression extrême).',
          'Des implémentations communautaires existent ; dans les sources que nous avons consultées, l\'article de blog de Google ne renvoie à aucun code officiel. Les chiffres ci-dessus sont rapportés par Google Research ; les taux de compression diffèrent d\'une implémentation communautaire à l\'autre.',
          '**Pourquoi c\'est important:** Une réduction mémoire purement logicielle ne nécessite aucun matériel nouveau et pourrait aider les appareils actuels dès qu\'une bibliothèque d\'inférence la prend en charge. C\'est une réponse pragmatique au goulot d\'étranglement mémoire en attendant la maturité de MRAM.',
        ],
      },
      'consumer-impact': {
        id: 'consumer-impact',
        title: 'Si MRAM atteint les appareils grand public',
        content: [
          'L\'adoption de MRAM par les smartphones et PC grand public transformerait l\'IA sur appareil de trois façons:',
        ],
        items: [
          '**Inférence instantanée:** Le téléphone démarre, les poids du modèle IA sont déjà dans la MRAM non-volatile du SoC, aucun rechargement depuis le stockage nécessaire. Démarrage instantané pour les assistants vocaux, la traduction en temps réel, le raisonnement sur appareil.',
          '**Longévité de batterie:** Aucune décharge de rafraîchissement en veille sur le sous-système mémoire. Pour les fonctionnalités IA always-on (écoute en arrière-plan, analyses respectueuses de la vie privée), les économies d\'énergie sont multiplicatives.',
          '**Modèles plus grands à budget énergétique fixe:** Si le calcul en mémoire apporte un gain d\'efficacité énergétique suffisant par rapport à la LPDDR5 avec calcul séparé, les téléphones pourraient en principe exécuter des modèles embarqués plus grands avec le même budget de batterie. C\'est spéculatif ; aucun gain de ce type n\'a été vérifié dans un produit commercial.',
        ],
        note: 'Cependant, ces bénéfices sont conditionnés à ce que MRAM atteigne les cibles de densité et de coût grand public. L\'eMRAM actuelle convient aux petits caches (1–100 Mo embarqués dans les microcontrôleurs et SoC d\'IA d\'edge). Un déploiement à l\'échelle du téléphone (équivalent de 8–16 Go de mémoire unifiée) exigerait des fonderies qu\'elles résolvent des défis de densité et de rendement encore non résolus.',
      },
