    leadAnswerBlock: '**A MRAM é uma memória magnética não volátil sem refresh; a computação em memória executa cálculos neurais dentro do array. Promissora, mas não comprovada para IA local: não se conhece nenhum chip de computação MRAM enviado, e a MRAM complementa a DRAM. Consumo: provavelmente 3–5+ anos (estimativa editorial).**',
