        imageCaption: 'Custo energético por operação de 32 bits: o acesso à DRAM custa 500+ pJ (>130x uma multiplicação de ponto flutuante de 32 bits), o acesso à SRAM ~5 pJ, e a própria multiplicação apenas ~3,7 pJ (valores aproximados a 45 nm, Horowitz, ISSCC 2014; nós modernos diferem).',
