        items: [
          'Os pesos da rede neural são armazenados como células MRAM (ou outra memória compatível com processamento analógico).',
          'As ativações de entrada são aplicadas como tensões de linha.',
          'As propriedades analógicas do array de memória calculam a multiplicação matriz-vetor em uma única passagem — a operação central na inferência de transformers.',
          'Os resultados são lidos e requantizados de volta para digital.',
        ],
        note: 'Por que isso importa: Na etapa central de multiplicação-acumulação, os dados não precisam trafegar entre uma memória e um processador separados, o que poderia reduzir a energia das transferências de DRAM (500+ pJ por acesso de 32 bits nas estimativas acima). Para dispositivos limitados por bateria, isso pode reduzir a energia por inferência; o tamanho do ganho depende da carga de trabalho e de quão bem a arquitetura de computação em memória se ajusta à rede neural. Ainda não existe número verificado de forma independente para um produto comercial de computação MRAM.',
