      'faqSection': {
        id: 'faq',
        title: 'Perguntas frequentes',
        faqs: [
          {
            q: 'A MRAM está disponível para comprar agora para meu PC ou celular?',
            a: 'Não. A MRAM está em produção em vários fornecedores, por exemplo para produtos industriais e de data center (veja o Form 8-K da Everspin citado acima). Para IA de consumo, ainda está apenas em P&D. O chip da SemiFive/ICYTech continua em estágio de tape-out — o silício ainda não retornou nem foi avaliado. A implantação de consumo está realistamente a 3–5+ anos.',
          },
          {
            q: 'A MRAM vai substituir a VRAM da minha GPU?',
            a: 'Improvável no curto prazo. A MRAM se destaca em baixo consumo em espera e não-volatilidade, o que importa em dispositivos de borda limitados por bateria. A HBM resolve um problema diferente: largura de banda máxima para treinamento em data center e inferência de grandes lotes. Para celulares de consumo e IA de borda especializada, a MRAM pode se tornar um componente (cache embarcado ou bloco acelerador). A VRAM de uma GPU de jogos ou de um acelerador de data center continuará sendo HBM ou GDDR no futuro previsível.',
          },
          {
            q: 'Qual a diferença entre computação em memória e banco de dados vetorial?',
            a: 'São camadas diferentes. Bancos de dados vetoriais armazenam embeddings e os recuperam por similaridade (usados em pipelines de RAG). A computação em memória executa a operação central da rede neural (multiplicação matriz-vetor) dentro da própria memória, eliminando a transferência de dados. Você poderia usar ambos juntos: computação em memória para o motor de inferência, banco de dados vetorial para a recuperação.',
          },
          {
            q: 'Posso usar a compressão TurboQuant no meu LLM local rodando hoje?',
            a: 'Ainda não nas bibliotecas de inferência mainstream, mas existem implementações da comunidade. O TurboQuant é um trabalho acadêmico (ICLR 2026). Não encontramos suporte confirmado ao TurboQuant no Ollama nem no LM Studio, e a postagem do blog do Google não aponta para código oficial; verifique o GitHub em busca de implementações da comunidade, cujas taxas de compressão e acurácia variam. A ideia central — quantizar agressivamente o cache KV — é reproduzível em código de inferência personalizado.',
          },
          {
            q: 'A MRAM funciona com transformers?',
            a: 'A Samsung a demonstrou em tarefas clássicas de ML (classificação de dígitos, detecção facial). A inferência em escala de transformer (modelos de 7B+) em computação em memória MRAM ainda não foi publicada. É plausível, mas não comprovada. O chip da SemiFive alega capacidade de 2B parâmetros; teremos benchmarks reais quando o silício retornar e for enviado.',
          },
          {
            q: 'A MRAM é o mesmo que 3D XPoint (Intel Optane)?',
            a: 'Não. O 3D XPoint era uma tecnologia de memória classe de armazenamento desenvolvida pela Intel e pela Micron (agora descontinuada). A MRAM armazena dados magneticamente; o 3D XPoint funciona com um mecanismo diferente. Ambas miram o mesmo espaço de problema — armazenamento rápido, durável e não-volátil — mas usam abordagens diferentes.',
          },
          {
            q: 'Quanta energia a MRAM economiza em comparação com a DRAM?',
            a: 'Em espera: a MRAM é não volátil e não precisa de refresh, evitando a energia de refresh que a DRAM consome; não encontramos um valor por gigabyte independente de fabricantes, e a economia depende do dispositivo e da capacidade. Para inferência ativa com computação em memória: o artigo da Samsung na Nature apresenta a computação analógica em memória como uma abordagem potencialmente de baixo consumo, mas não encontramos nele uma economia quantificada em relação à DRAM. Números de silício comercial virão quando um produto for enviado e avaliado de forma independente.',
          },
          {
            q: 'A MRAM vai substituir a DRAM?',
            a: 'Não como memória principal no futuro previsível. As forças da MRAM são a não volatilidade e a ausência de energia de refresh, que se adequam a caches embarcados e aceleradores de borda de baixo consumo. DRAM e HBM ainda mantêm vantagens em densidade, largura de banda e custo por bit. O papel realista da MRAM é ser um bloco não volátil complementar ou uma unidade de computação em memória, não uma substituta da DRAM.',
          },
          {
            q: 'A Qualcomm resolveu o gargalo de memória em 2026?',
            a: 'A Qualcomm apresentou o HBC (High-Bandwidth Compute) sob a marca Dragonfly em seu Investor Day de 2026: um design near-memory que une computação e memória em silício empilhado em 3D, com a Qualcomm afirmando cerca de 6 vezes mais largura de banda por watt do que a HBM e 200 vezes mais capacidade por watt do que a SRAM (números do fabricante, não verificados de forma independente). A Meta assinou um acordo de várias gerações para usar a CPU de servidor Dragonfly C1000; nas fontes que verificamos, a Qualcomm não nomeou clientes para os aceleradores AI250 e AI300 que usam HBC. Três distinções continuam importantes: o HBC é near-memory (computação ao lado da memória), não computação em memória com MRAM (computação dentro do array de memória); ele mira aceleradores de IA de data center, não celulares; e a amostragem comercial da primeira geração do HBC (AI250) é esperada para meados de 2027 e a do HBC Gen 2 (AI300) para 2028, então nada foi enviado. É uma abordagem diferente para o mesmo problema da muralha de memória, não um avanço da MRAM.',
          },
        ],
      },
