        imageCaption: 'تكلفة الطاقة لكل عملية 32 بت: الوصول إلى DRAM يكلف أكثر من 500 بيكوجول (أكثر من 130 ضعف عملية ضرب بفاصلة عائمة 32-bit)، والوصول إلى SRAM ~5 بيكوجول، بينما عملية الضرب نفسها ~3.7 بيكوجول فقط (أرقام تقريبية عند 45 nm حسب Horowitz، ISSCC 2014؛ وتختلف عقد التصنيع الحديثة).',
