        imageCaption: '32비트 연산당 에너지 비용: DRAM 액세스는 500pJ 이상(32비트 부동소수점 곱셈의 130배 이상), SRAM 액세스는 약 5pJ, 곱셈 연산 자체는 약 3.7pJ에 불과(45nm 부근 근사값, Horowitz, ISSCC 2014; 최신 공정 노드는 다릅니다).',
